                {
                    "@type": "Question",
                    "name": "Bagaimana pengaturan kamar jika ada pejabat Eselon II yang berhak atas kamar single sesuai SBM?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Kami memisahkan alokasi kamar single untuk pejabat eselon II/I dan kamar twin sharing untuk staf/eselon III-IV sesuai ketentuan plafon SBM perorangan tanpa mencampuradukkan tagihan."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Apakah peserta dari luar kota bisa difasilitasi penjemputannya dari bandara atau stasiun?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Bisa. Kami menyediakan armada HiAce Luxury atau Bus Pariwisata AC khusus penjemputan delegasi dari Bandara YIA Jogja, Adi Soemarmo Solo, atau stasiun kereta menuju hotel."
                    }
                },
                {
                    "@type": "Question",
                    "name": "Apakah paket ini dapat dipesan melalui mekanisme Pengadaan Langsung di bawah Rp 200 juta?",
                    "acceptedAnswer": {
                        "@type": "Answer",
                        "text": "Ya, sebagian besar paket konsinyering instansi berada pada rentang Rp 40 juta hingga Rp 180 juta yang sangat sesuai dengan mekanisme Pengadaan Langsung SPK di sistem SPSE LPSE."
                    }
                }
            ]
        }
    ]
}

inline_styles:
/* Program Detail Page Styling */
.eo-detail-hero {
  background: linear-gradient(135deg, #091a2e 0%, #0d2847 50%, #081d33 100%);
  color: #fff;
  padding: 56px 0 46px;
  border-bottom: 4px solid #2563eb;
}
.eo-detail-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 16px;
}
.eo-badge-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(37, 99, 235, 0.2);
  border: 1px solid rgba(96, 165, 250, 0.45);
  color: #93c5fd;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  padding: 5px 12px;
  border-radius: 6px;
}
.eo-badge-item.gold {
  background: rgba(245, 158, 11, 0.2);
  border-color: rgba(245, 158, 11, 0.5);
  color: #fde68a;
}
.eo-detail-hero h1 {
  font-size: clamp(24px, 3.8vw, 40px);
  font-weight: 800;
  line-height: 1.25;
  color: #fff;
  margin: 0 0 16px;
}
.eo-detail-hero p.tagline {
  font-size: clamp(15px, 1.8vw, 17.5px);
  color: #cbd5e1;
  max-width: 840px;
  line-height: 1.6;
  margin-bottom: 26px;
}
.eo-meta-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 12px;
  padding: 18px 22px;
}
.eo-meta-item {
  flex: 1;
  min-width: 180px;
}
.eo-meta-item span.lbl {
  display: block;
  font-size: 11px;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: .05em;
  margin-bottom: 4px;
}
.eo-meta-item strong {
  font-size: 14.5px;
  color: #fff;
  font-weight: 700;
}
.eo-meta-item strong.price {
  color: #38bdf8;
  font-size: 16px;
}

/* Two-column Layout */
.eo-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 40px;
  padding: 44px 0 60px;
}
@media (max-width: 991px) {
  .eo-layout {
    grid-template-columns: 1fr;
  }
}

.eo-body {
  font-size: 15.5px;
  line-height: 1.8;
  color: #334155;
}
.eo-body h2 {
  font-size: 23px;
  font-weight: 800;
  color: #0f172a;
  margin: 36px 0 14px;
  padding-bottom: 8px;
  border-bottom: 2px solid #e2e8f0;
}
.eo-body h3 {
  font-size: 18.5px;
  font-weight: 800;
  color: #0f172a;
  margin: 28px 0 12px;
}
.eo-body p {
  margin-bottom: 18px;
  white-space: pre-line;
}

/* Technical Specification Table */
.eo-spec-table {
  width: 100%;
  border-collapse: collapse;
  margin: 22px 0 32px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  overflow: hidden;
  font-size: 14px;
}
.eo-spec-table th {
  background: #0f172a;
  color: #fff;
  padding: 12px 16px;
  text-align: left;
  font-weight: 700;
  font-size: 13px;
}
.eo-spec-table td {
  padding: 13px 16px;
  border-bottom: 1px solid #f1f5f9;
  vertical-align: top;
  color: #334155;
}
.eo-spec-table tr:hover td {
  background: #f8fafc;
}
.eo-spec-table td strong {
  color: #0f172a;
}

/* Rundown Schedule Box */
.eo-rundown-box {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 24px;
  margin: 24px 0 32px;
}
.eo-rundown-item {
  display: flex;
  gap: 16px;
  margin-bottom: 16px;
  padding-bottom: 16px;
  border-bottom: 1px dashed #cbd5e1;
}
.eo-rundown-item:last-child {
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: none;
}
.eo-time-badge {
  background: #0f172a;
  color: #38bdf8;
  font-weight: 800;
  font-size: 12.5px;
  padding: 6px 12px;
  border-radius: 8px;
  height: fit-content;
  white-space: nowrap;
}
.eo-rundown-content h3,
.eo-rundown-content h4 {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: #1e293b;
  line-height: 1.5;
}

/* Deliverables Cards */
.eo-deliv-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 14px;
  margin: 20px 0 32px;
}
.eo-deliv-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #2563eb;
  border-radius: 8px;
  padding: 14px 16px;
  font-size: 13.5px;
  color: #334155;
  line-height: 1.5;
  box-shadow: 0 2px 6px rgba(0,0,0,0.02);
}

/* Procurement Workflow Steps */
.eo-flow-box {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 24px;
  margin: 24px 0 32px;
}
.eo-flow-step {
  display: flex;
  gap: 16px;
  margin-bottom: 16px;
}
.eo-flow-step:last-child {
  margin-bottom: 0;
}
.eo-step-num {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #2563eb;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 14px;
  flex-shrink: 0;
}
.eo-step-info strong {
  display: block;
  font-size: 15px;
  color: #0f172a;
  margin-bottom: 4px;
}
.eo-step-info span {
  font-size: 13.5px;
  color: #64748b;
  line-height: 1.5;
}

/* Sidebar Widgets */
.eo-sidebar-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 24px;
  margin-bottom: 24px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.03);
}
.eo-sidebar-card h3 {
  font-size: 17px;
  font-weight: 800;
  color: #0f172a;
  margin: 0 0 12px;
}
.eo-sidebar-card p {
  font-size: 13.5px;
  color: #64748b;
  line-height: 1.55;
  margin-bottom: 16px;
}
.eo-sidebar-price {
  background: #f8fafc;
  border-radius: 10px;
  padding: 14px;
  margin-bottom: 18px;
  border: 1px solid #e2e8f0;
}
.eo-sidebar-price span {
  display: block;
  font-size: 12px;
  color: #64748b;
  margin-bottom: 4px;
}
.eo-sidebar-price strong {
  font-size: 18px;
  color: #0f172a;
}
.eo-sidebar-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: #25D366;
  color: #fff;
  font-weight: 700;
  font-size: 14.5px;
  padding: 13px;
  border-radius: 10px;
  text-decoration: none;
  box-shadow: 0 4px 12px rgba(37, 211, 102, 0.3);
  transition: background .2s ease;
}
.eo-sidebar-btn:hover {
  background: #20ba5a;
  color: #fff;
}
.eo-tender-badge-list {
  list-style: none;
  padding: 0;
  margin: 0;
  font-size: 12.5px;
  color: #475569;
}
.eo-tender-badge-list li {
  padding: 8px 0;
  border-bottom: 1px solid #f1f5f9;
  display: flex;
  align-items: center;
  gap: 8px;
}
.eo-tender-badge-list li:last-child {
  border-bottom: none;
}
.eo-tender-badge-list svg {
  color: #2563eb;
  flex-shrink: 0;
}

/* Related Programs Grid */
.eo-related-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
  margin-top: 24px;
}
.eo-related-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 20px;
  transition: transform .2s ease, border-color .2s ease;
}
.eo-related-card:hover {
  transform: translateY(-3px);
  border-color: #93c5fd;
}
.eo-related-card h3,
.eo-related-card h4 {
  font-size: 16px;
  font-weight: 800;
  margin: 0 0 8px;
  color: #0f172a;
  line-height: 1.35;
}
.eo-related-card h3 a,
.eo-related-card h4 a {
  color: inherit;
  text-decoration: none;
}
.eo-related-card h3 a:hover,
.eo-related-card h4 a:hover {
  color: #2563eb;
}
.eo-related-card p {
  font-size: 13px;
  color: #64748b;
  margin: 0 0 12px;
  line-height: 1.5;
}
.eo-related-card a.link {
  font-size: 13px;
  font-weight: 700;
  color: #2563eb;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
